package com.nigson.acceptance.order;
import java.util.*;
import java.time.*;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.security.PrivateWorkload;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import com.nigson.commerce.order.*;
import static org.assertj.core.api.Assertions.*;
class OrderCancellationPersistenceTest {
 OrderFixture f;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null&&System.getenv("NIGSON_TEST_ORDER_PAYSTACK")!=null,"isolated database/provider required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");f=new OrderFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 OrderValues.Order request(OrderValues.Order o,String key){return f.service.cancelled(f.prices.customer,o.id(),o.version(),"Customer requests cancellation",key,UUID.randomUUID());}
 OrderValues.Order paid(){var checkout=f.checkout("paid");f.progress(checkout,"success");f.payments.inspect(checkout.order().id(),UUID.randomUUID());return f.service.get(f.prices.customer,checkout.order().id());}
 @Test void paidCancellationReleasesAllocationAndRequestsOneFinanceApprovedRefund(){var o=paid();var accepted=request(o,"cancel");assertThat(accepted.cancellation().state()).isEqualTo("REQUESTED");assertThatThrownBy(()->f.service.processing(f.operations,o.id(),accepted.version(),"Cannot prepare cancelled order","process",UUID.randomUUID())).hasMessage("INVALID_TRANSITION");f.cancellations.process(o.id());f.cancellations.process(o.id());var cancelled=f.service.get(f.prices.customer,o.id());assertThat(cancelled.status()).isEqualTo("CANCELLED");assertThat(cancelled.paymentStatus()).isEqualTo("PAID");assertThat(cancelled.cancellation().refundState()).isEqualTo("REQUESTED");assertThat(f.stock("on_hand")).isEqualByComparingTo("5");assertThat(f.stock("allocated")).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.refund WHERE order_id=?",Integer.class,o.id())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT amount FROM commerce.refund WHERE order_id=?",java.math.BigDecimal.class,o.id())).isEqualByComparingTo(o.totals().grandTotal());assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=? AND event_type='order.cancelled.v1'",Integer.class,o.id())).isEqualTo(1);assertThat(request(o,"cancel")).isEqualTo(cancelled);f.tx.executeWithoutResult(s->f.lifecycle.settled(o.id(),UUID.randomUUID()));assertThat(f.stock("allocated")).isZero();}
 @Test void paymentSuccessDuringCancellationNeverAllocatesStockOrReopensFulfillment(){var checkout=f.checkout("race");request(checkout.order(),"cancel");f.progress(checkout,"success");f.cancellations.process(checkout.order().id());var o=f.service.get(f.prices.customer,checkout.order().id());assertThat(o.status()).isEqualTo("CANCELLED");assertThat(o.paymentStatus()).isEqualTo("PAID");assertThat(o.cancellation().refundState()).isEqualTo("REQUESTED");assertThat(f.stock("allocated")).isZero();assertThat(f.stock("reserved")).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_movement WHERE order_id=? AND movement_type='SETTLE'",Integer.class,o.id())).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.payment_transaction WHERE attempt_id=?",Integer.class,checkout.payment().attemptId())).isEqualTo(1);}
 @Test void staleVersionWrongOwnerAndShippedOrderAreDenied(){var o=paid();assertThatThrownBy(()->f.service.cancelled(f.prices.customer,o.id(),0,"Customer requests cancellation","stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");var other=f.secondBuyer();assertThatThrownBy(()->f.service.cancelled(other.actor(),o.id(),o.version(),"Customer requests cancellation","owner",UUID.randomUUID())).hasMessage("NOT_FOUND");f.jdbc.update("UPDATE commerce.sales_order SET status='SHIPPED' WHERE id=?",o.id());assertThatThrownBy(()->request(o,"shipped")).hasMessage("INVALID_TRANSITION");}
 @Test void simultaneousRequestsAndWorkersCreateOneRefundAndOneStockRelease()throws Exception{var o=paid();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();try{return (Object)request(o,"same-key");}catch(com.nigson.commerce.platform.PlatformStore.Conflict conflict){assertThat(conflict.getMessage()).isEqualTo("IDEMPOTENCY_IN_PROGRESS");return conflict.getMessage();}});var b=pool.submit(()->{gate.await();try{return (Object)request(o,"same-key");}catch(com.nigson.commerce.platform.PlatformStore.Conflict conflict){assertThat(conflict.getMessage()).isEqualTo("IDEMPOTENCY_IN_PROGRESS");return conflict.getMessage();}});gate.countDown();var first=a.get(15,TimeUnit.SECONDS);var second=b.get(15,TimeUnit.SECONDS);assertThat(List.of(first,second).stream().filter(x->x instanceof OrderValues.Order).count()).isGreaterThanOrEqualTo(1);assertThat(request(o,"same-key").cancellation()).isNotNull();var c=pool.submit(()->f.cancellations.process(o.id()));var d=pool.submit(()->f.cancellations.process(o.id()));c.get(15,TimeUnit.SECONDS);d.get(15,TimeUnit.SECONDS);}assertThat(f.stock("allocated")).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.refund WHERE order_id=?",Integer.class,o.id())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_movement WHERE order_id=? AND return_kind='UNSHIPPED_CANCEL'",Integer.class,o.id())).isEqualTo(1);}
 @Test void cashOnDeliveryCancellationReleasesStockWithoutCreatingRefundOrExpiringConvertedCart(){var checkout=f.service.checkout(f.prices.customer,new OrderValues.CheckoutInput(f.quote.id(),f.quote.quoteHash(),"CASH_ON_DELIVERY"),"cod",UUID.randomUUID());request(checkout.order(),"cancel-cod");f.cancellations.process(checkout.order().id());var o=f.service.get(f.prices.customer,checkout.order().id());assertThat(o.status()).isEqualTo("CANCELLED");assertThat(o.paymentStatus()).isEqualTo("UNPAID");assertThat(o.cancellation().refundState()).isNull();assertThat(f.stock("allocated")).isZero();assertThat(f.stock("on_hand")).isEqualByComparingTo("5");assertThat(f.jdbc.queryForObject("SELECT status FROM commerce.cart WHERE id=?",String.class,f.prices.cart)).isEqualTo("CONVERTED");assertThat(f.state().path("operations")).isEmpty();}

 JdbcShipmentRepository shipments(){var clock=Clock.systemUTC();return new JdbcShipmentRepository(f.jdbc,clock,new FulfillmentPolicy(true,"test","MOCK","SYNTHETIC_BOOKING_APPROVAL",clock.instant().plusSeconds(600),null,Set.of(),clock,"1".repeat(64)));}
 UUID shipment(OrderValues.Order order){return f.tx.execute(s->shipments().create(order.id(),new FulfillmentValues.ShipmentInput(List.of(new FulfillmentValues.LineInput(order.lines().getFirst().id(),f.balance,"2")),"PANDAGO",null,null),"synthetic-shipment").id());}
 CarrierCancellationService carrier(){var clock=Clock.systemUTC();return new CarrierCancellationService(f.jdbc,shipments(),new com.nigson.commerce.inventory.InventoryAuthority(f.jdbc),new PlatformStore(f.jdbc,f.tx.getTransactionManager(),clock,f.prices.metrics),new AuditWriter(f.jdbc,clock,f.prices.metrics),new FulfillmentPolicy(true,"test","MOCK","SYNTHETIC_BOOKING_APPROVAL",clock.instant().plusSeconds(600),null,Set.of(),clock,"1".repeat(64)),f.tx.getTransactionManager(),clock);}
 void receipt(UUID shipment,String state){var row=f.jdbc.queryForMap("SELECT * FROM commerce.carrier_cancellation WHERE shipment_id=?",shipment);var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-199")).findFirst().orElseThrow();carrier().accept(new PrivateWorkload.Proof("nigson-integration","synthetic-integration",route,null),new CarrierCancellationValues.Receipt(UUID.randomUUID(),(UUID)row.get("id"),shipment,(UUID)row.get("booking_request_id"),row.get("reference").toString(),"MOCK",state,Instant.now(),state.equals("CANCELLED")?"NONE":state.equals("REJECTED")?"CARRIER_CANCEL_REJECTED":"PROVIDER_OUTCOME_UNKNOWN"),UUID.randomUUID());}
 @Test void deliveryConfirmationPrecedesStockReleaseAndRefundAndDispatchIsExcluded(){var o=paid();UUID shipment=shipment(o);request(f.service.get(f.prices.customer,o.id()),"cancel-booking");f.cancellations.process(o.id());assertThat(f.service.get(f.prices.customer,o.id()).cancellation().state()).isEqualTo("WAITING_CARRIER");assertThat(f.stock("allocated")).isEqualByComparingTo("2");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.refund WHERE order_id=?",Integer.class,o.id())).isZero();assertThatThrownBy(()->f.tx.execute(s->shipments().dispatch(shipment,0,"synthetic"))).hasMessage("INVALID_TRANSITION");receipt(shipment,"UNKNOWN");f.cancellations.process(o.id());assertThat(f.stock("allocated")).isEqualByComparingTo("2");receipt(shipment,"CANCELLED");f.cancellations.process(o.id());assertThat(f.service.get(f.prices.customer,o.id()).status()).isEqualTo("CANCELLED");assertThat(f.stock("allocated")).isZero();assertThat(f.service.get(f.prices.customer,o.id()).cancellation().refundState()).isEqualTo("REQUESTED");}
 @Test void providerRefusalPreservesStockAndDoesNotRefund(){var o=paid();UUID shipment=shipment(o);request(o,"cancel-rejected");f.cancellations.process(o.id());receipt(shipment,"REJECTED");f.cancellations.process(o.id());var result=f.service.get(f.prices.customer,o.id());assertThat(result.cancellation().state()).isEqualTo("REJECTED");assertThat(result.status()).isEqualTo("PAID");assertThat(f.stock("allocated")).isEqualByComparingTo("2");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.refund WHERE order_id=?",Integer.class,o.id())).isZero();}
 @Test void acceptedCancellationPreventsAutomaticShipmentIntake(){var o=paid();request(o,"cancel-before-intake");var clock=Clock.systemUTC();var worker=new AutomaticShipmentWorker(f.jdbc,shipments(),new PlatformStore(f.jdbc,f.tx.getTransactionManager(),clock,f.prices.metrics),new AuditWriter(f.jdbc,clock,f.prices.metrics),f.tx.getTransactionManager(),clock,clock.instant().minusSeconds(600));assertThat(worker.poll()).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.shipment WHERE order_id=?",Integer.class,o.id())).isZero();}

 @Test void populatedCancellationMigrationRollbackRefusesBeforeDroppingEvidence()throws Exception{var o=paid();request(o,"cancel-rollback");String rollback=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/resources/db/changelog/036-bp1-order-cancellation-rollback.sql"));assertThatThrownBy(()->f.prices.admin.execute(rollback)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.service.get(f.prices.customer,o.id()).cancellation().state()).isEqualTo("REQUESTED");}

 @Test void cancellationBeforePaymentInitializationPreventsLaunchingHostedCheckout(){var pending=f.tx.execute(s->f.service.pending(f.prices.customer,f.input,UUID.randomUUID()));request(pending.order(),"cancel-created");assertThatThrownBy(()->f.payments.initialize(pending.order().id(),UUID.randomUUID())).hasMessage("INVALID_TRANSITION");f.cancellations.process(pending.order().id());assertThat(f.service.get(f.prices.customer,pending.order().id()).status()).isEqualTo("CANCELLED");assertThat(f.stock("reserved")).isZero();assertThat(f.state().path("operations")).isEmpty();}

}
